[{"order":1,"type":"heading","text":"Mastering Advanced Data Types in PostgreSQL"},{"order":2,"type":"paragraph","text":"PostgreSQL is renowned for its robust extension ecosystem and rich set of native data types. Beyond standard integers, strings, and timestamps, PostgreSQL offers advanced data types such as JSONB, Arrays, Ranges, and UUIDs. These types allow developers to build flexible schemas without sacrificing relational integrity."},{"order":3,"type":"subheading","text":"1. JSONB (Binary JSON)"},{"order":4,"type":"paragraph","text":"Unlike the standard json type, jsonb stores data in a decomposed binary format. While it takes slightly more time to input due to conversion overhead, it is significantly faster to process because parsing is not required on each query. It also supports indexing."},{"order":5,"type":"code","text":"CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100),
    preferences JSONB
);

INSERT INTO users (name, preferences) 
VALUES ('Alice', '{"theme": "dark", "notifications": {"email": true, "sms": false}}');"},{"order":6,"type":"paragraph","text":"You can query nested JSON fields using the arrow operators -> (returns JSONB) and ->> (returns text). To query nested attributes efficiently, use the containment operator @>."},{"order":7,"type":"code","text":"SELECT name FROM users WHERE preferences -> 'notifications' ->> 'email' = 'true';

-- Using the containment operator
SELECT name FROM users WHERE preferences @> '{"theme": "dark"}';"},{"order":8,"type":"subheading","text":"2. Arrays"},{"order":9,"type":"paragraph","text":"PostgreSQL allows columns of a table to be defined as variable-length multidimensional arrays. Any built-in or user-defined base type can have an array type."},{"order":10,"type":"code","text":"CREATE TABLE articles (
    id SERIAL PRIMARY KEY,
    title VARCHAR(200),
    tags TEXT[]
);

INSERT INTO articles (title, tags) 
VALUES ('Postgres Advanced', ARRAY['database', 'sql', 'performance']);"},{"order":11,"type":"paragraph","text":"You can query arrays using the ANY operator or overlap operators to find records containing specific array elements."},{"order":12,"type":"code","text":"SELECT title FROM articles WHERE 'sql' = ANY(tags);

-- Overlap operator (&&)
SELECT title FROM articles WHERE tags && ARRAY['database', 'nosql'];"},{"order":13,"type":"subheading","text":"3. Range Types"},{"order":14,"type":"paragraph","text":"Range types represent a set of values of some specific data type (called the range\'s subtype). Built-in ranges include int4range, int8range, numrange, tsrange, tstzrange, and daterange."},{"order":15,"type":"code","text":"CREATE TABLE room_bookings (
    room_id INT,
    booking_period TSTZRANGE
);

INSERT INTO room_bookings VALUES 
(101, tstzrange("2023-11-01 09:00:00+00", "2023-11-01 17:00:00+00"));"},{"order":16,"type":"paragraph","text":"Ranges are particularly powerful when combined with exclusion constraints to prevent overlapping bookings."},{"order":17,"type":"code","text":"ALTER TABLE room_bookings ADD CONSTRAINT no_overlap 
EXCLUDE USING gist (room_id WITH =, booking_period WITH &&);"},{"order":18,"type":"subheading","text":"4. UUIDs (Universally Unique Identifiers)"},{"order":19,"type":"paragraph","text":"UUIDs are 128-bit quantities generated by algorithms that guarantee uniqueness across space and time. They are ideal for distributed systems where primary keys cannot be generated sequentially by a single database."},{"order":20,"type":"code","text":"CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE orders (
    order_id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    total NUMERIC(10, 2)
);

INSERT INTO orders (total) VALUES (150.00);"},{"order":21,"type":"bullet_point","text":"Use JSONB for flexible, semi-structured schemas that require frequent attribute-level querying."},{"order":22,"type":"bullet_point","text":"Use Arrays for homogeneous lists of scalar values, but avoid them if normalization and foreign keys are needed."},{"order":23,"type":"bullet_point","text":"Use Ranges and exclusion constraints to elegantly solve scheduling and interval overlap problems."},{"order":24,"type":"bullet_point","text":"Use UUIDs for distributed architectures to prevent primary key collisions."}]
